@startuml

class Organizer {
  + FirstName : string
  + LastName : string
  + Email : string
  + Address : string
  + PhoneNumber : string
  + Password : string
}

class Attendee {
  + FirstName : string
  + LastName : string
  + Email : string
  + Password : string
  + AttendanceStatus : string
}

class EventType {
  + Name : string
}

class Location {
  + Name : string
  + Address : string
}

class Event {
  + Occasion : string
  + StartDateTime : datetime
  + EndDateTime : datetime
}

class Task {
  + Description : string
  + Status : string
  + IsAssignedToAttendee : boolean
}

class TaskAssignment {
  + IsSelected : boolean
}

enum AttendanceStatus {
  ATTENDING
  MAYBE
  NOT_ATTENDING
}

enum TaskStatus {
  NEEDS_TO_BE_DONE
  DONE
  NOT_APPLICABLE
}

Organizer "1..*" -- "1..*" Event : organizes
Organizer "0..*" -- "0..*" Event : attends
Attendee "0..*" -- "0..*" Event : attends

Event "1" -- "1" EventType
Event "1" -- "1" Location
Event "1" *-- "0..*" Task

Task "0..*" -- "0..1" Attendee : assigned to
Task "0..*" -- "0..*" Attendee : brings

@enduml

